static inline void load_data(u8* dest, const u8* src, size_t n) {
  if (!n) {
    return;
  }
#if WABT_BIG_ENDIAN
  for (size_t i = 0; i < n; i++) {
    dest[i] = src[n - i - 1];
  }
#else
  wasm_rt_memcpy(dest, src, n);
#endif
}

